  "pba4f6d30": "<p>1. <a data-page=\"Menu_Costing.htm\">Menu Costing</a></p> <p>2. <a data-page=\"Menu_Sales_Report.htm\">Menu Sales Report</a></p> <p>3. <a data-page=\"End-of-Day_Inventory.htm\">End-of-Day Inventory</a></p> <p>4. <a data-page=\"Production_Transaction.htm\">Production Transaction</a></p> <p>5. <a data-page=\"Production_Receipts.htm\">Production Receipts</a></p> <p>6. <a data-page=\"Production_Reports.htm\">Production Reports</a></p>",
